output_text:
[
  {
    "id": "return_cart_to_corral",
    "text": "A shopper who enters with access to a cart is obliged to return the cart to the return corral at (0,1) before leaving.",
    "abstraction": {
      "state_properties": {
        "at_return_corral": "at(0,1)",
        "cart_parked_in_return_corral": "cartAt(0,1)"
      },
      "events": {
        "return_cart_to_corral": {
          "pre": {
            "and": [
              "at_return_corral",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_corral"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart_to_corral"
    }
  },
  {
    "id": "must_take_entrance_cart",
    "text": "A shopper is obliged to take the available cart from the entrance cart station before shopping.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_station": "at(1,5)",
        "cart_waiting_at_entrance": "cartAt(1,5)"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "at_entrance_cart_station",
              "cart_waiting_at_entrance",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "no_hand_carrying_groceries",
    "text": "Groceries should be placed in a cart rather than carried by hand.",
    "abstraction": {
      "state_properties": {
        "cart_possessed": "hasCart",
        "carrying_item_by_hand": "handFull"
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "cart_possessed"
              }
            ]
          },
          "post": "carrying_item_by_hand"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_item_by_hand",
          "pickup_item_without_cart"
        ]
      }
    }
  },
  {
    "id": "leave_cart_only_at_corral",
    "text": "A cart may only be left unattended in the designated return corral at (0,1).",
    "abstraction": {
      "state_properties": {
        "at_return_corral": "at(0,1)"
      },
      "events": {
        "leave_cart_outside_corral": {
          "pre": {
            "and": [
              "hasCart",
              "LEAVE_CART",
              {
                "not": "at_return_corral"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_corral"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "Shoppers are forbidden from taking a cart through the store exit.",
    "abstraction": {
      "state_properties": {
        "cart_possessed": "hasCart",
        "at_exit": "at(9,5)"
      },
      "events": {
        "exit_while_pushing_cart": {
          "pre": {
            "and": [
              "at_exit",
              "cart_possessed",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_while_pushing_cart"
    }
  },
  {
    "id": "no_carts_in_exit_zone",
    "text": "Carts are forbidden in the right-side exit zone, so shoppers must park them before walking to the exit.",
    "abstraction": {
      "state_properties": {
        "right_exit_zone": {
          "or": [
            "at(7,1)",
            "at(8,1)",
            "at(9,1)",
            "at(7,2)",
            "at(8,2)",
            "at(9,2)",
            "at(7,3)",
            "at(8,3)",
            "at(9,3)",
            "at(7,4)",
            "at(8,4)",
            "at(9,4)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "cart_possessed": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "right_exit_zone",
          "cart_possessed"
        ]
      }
    }
  },
  {
    "id": "return_cart_after_item_pickup",
    "text": "After putting any grocery item into a cart, the shopper is obliged eventually to return that cart to the corral.",
    "abstraction": {
      "state_properties": {
        "at_return_corral": "at(0,1)",
        "cart_parked_in_return_corral": "cartAt(0,1)"
      },
      "events": {
        "item_put_in_cart": {
          "pre": {
            "and": [
              "hasCart",
              "PICKUP_ITEM"
            ]
          },
          "post": "hasCart"
        },
        "return_cart_to_corral": {
          "pre": {
            "and": [
              "at_return_corral",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_corral"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "item_put_in_cart",
      "discharge": "return_cart_to_corral"
    }
  },
  {
    "id": "do_not_retake_returned_cart",
    "text": "Once a cart has been returned to the corral, it should not be picked up again for the exit walk.",
    "abstraction": {
      "state_properties": {
        "at_return_corral": "at(0,1)",
        "cart_parked_in_return_corral": "cartAt(0,1)"
      },
      "events": {
        "retake_returned_cart": {
          "pre": {
            "and": [
              "at_return_corral",
              "cart_parked_in_return_corral",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "retake_returned_cart"
    }
  }
]
